import{_ as a,o as t,c as o,a3 as d}from"./chunks/framework.B8xISX-C.js";const m=JSON.parse('{"title":"Copying an example","description":"","frontmatter":{"title":"Copying an example"},"headers":[],"relativePath":"guide/copying-an-example.md","filePath":"guide/copying-an-example.md"}'),s={name:"guide/copying-an-example.md"};function n(i,e,r,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="copying-an-example" tabindex="-1">Copying an example <a class="header-anchor" href="#copying-an-example" aria-label="Permalink to &quot;Copying an example&quot;">​</a></h1><p>This page is a checklist for starting a mod from one of the <a href="/carina-mod-template/examples/">example mods</a>. Each line gives the reason.</p><p>The template holds the examples under <code>mods/</code>. Copy the folder, then change each item below.</p><ol><li><strong>Id.</strong> Set a new <code>id</code> in <code>mod.json</code>. Two mods with one id are the same mod to the game, and saves and dependencies name a mod by its id.</li><li><strong>Record keys.</strong> The examples use the namespace <code>carina_team.&lt;slug&gt;</code>, with <code>-</code> read as <code>_</code>. Replace it with yours in every record key and every reference to a key: records, patches, <code>assets/roles.json</code> (<code>races</code> and <code>artFrom</code>) and migrations. A key outside your namespace is refused.</li><li><strong>Text keys.</strong> They hold the namespace too, for example <code>wpn.carina_team.prism_optics.prism_beam.name</code>. Rename them in the text files and in every <code>nameKey</code> and <code>descKey</code> that names them.</li><li><strong>Role names.</strong> An added race has role names that hold its key, such as <code>races.portrait.select.&lt;race key&gt;</code>. A building&#39;s lot role is <code>colony.lot.&lt;building key with _ written as -&gt;</code>. Rename both with the keys.</li><li><strong>Dependencies.</strong> Check the ids and ranges in <code>dependencies</code>, and <code>loadAfter</code>. Drop the ones your copy does not need.</li><li><strong>Version.</strong> Set <code>version</code> and <code>rulesVersion</code> back to their starting values, and delete the original&#39;s <code>migrations/</code> folder.</li><li><strong>Display fields.</strong> Set <code>title</code>, <code>summary</code> and <code>authors</code>.</li><li><strong>Licence.</strong> The examples are CC-BY-4.0. Set <code>license</code>. If you keep files of the example, list them in <code>sources</code> with the example&#39;s author and licence, and put the example&#39;s <code>packageHash</code> in <code>basedOn</code>. CC-BY-4.0 requires credit.</li><li><strong>Check it.</strong> Run <code>npx carina-modkit vscode</code> so the editor knows the new folder, then <code>npx carina-modkit check mods/&lt;your mod&gt;</code>.</li></ol><p>Walk the issues <code>check</code> prints. The first stage that fails stops the rest, so run it again after each fix.</p><h2 id="which-example" tabindex="-1">Which example <a class="header-anchor" href="#which-example" aria-label="Permalink to &quot;Which example&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To see</th><th>Copy</th></tr></thead><tbody><tr><td>A tech line, a weapon, a building and a balance patch</td><td><a href="/carina-mod-template/examples/prism-optics">Prism Optics</a></td></tr><tr><td>A race with all its art, a pick and a pick-exclusive weapon</td><td><a href="/carina-mod-template/examples/hollow-choir">Hollow Choir</a></td></tr><tr><td>A graphics and sound pack</td><td><a href="/carina-mod-template/examples/deep-field">Deep Field</a></td></tr><tr><td>A patch-only add-on for two other mods</td><td><a href="/carina-mod-template/examples/choir-prisms">Choir Prisms</a></td></tr><tr><td>Three patch rows and nothing else</td><td><a href="/carina-mod-template/examples/balance-tweaks">Balance Tweaks</a></td></tr><tr><td>A text-only pack that renames hull classes</td><td><a href="/carina-mod-template/examples/ship-class-names">Ship Class Names</a></td></tr><tr><td>An update with a save migration</td><td><a href="/carina-mod-template/examples/pulse-lance">Pulse Lance</a></td></tr></tbody></table>',7)])])}const g=a(s,[["render",n]]);export{m as __pageData,g as default};
